<script setup lang="ts">import type{Article}from'@career-launch/shared';import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{repository}from'../../services/repository';const route=useRoute();const article=ref<Article|null>(null);onMounted(async()=>{article.value=await repository.knowledge.getArticle(String(route.params.id))})</script>
<template><article v-if="article" class="cl-page article-page"><header><RouterLink to="/knowledge">返回面试宝典</RouterLink><h1>{{article.title}}</h1><p>{{article.summary}}</p><div>{{article.category}} · {{article.readingMinutes}} 分钟阅读 · {{new Date(article.publishedAt).toLocaleDateString('zh-CN')}}</div></header><section class="cl-card"><p v-for="paragraph in article.body.split('\n\n')" :key="paragraph">{{paragraph}}</p></section></article><section v-else class="cl-page cl-container">正在加载文章…</section></template>
<style scoped>.article-page{width:min(calc(100% - 32px),760px);margin:auto}.article-page header{padding:22px 0 30px}.article-page header>a{color:var(--cl-primary);font-weight:700}.article-page h1{margin:24px 0 12px;color:var(--cl-text-strong);font-size:42px;line-height:1.25;letter-spacing:-.04em}.article-page header p{color:var(--cl-muted);font-size:18px}.article-page header div{color:var(--cl-subtle);font-size:13px}.article-page section{padding:34px;font-size:17px;line-height:1.9}.article-page section p{margin-bottom:22px}@media(max-width:600px){.article-page h1{font-size:32px}.article-page section{padding:22px}}</style>
